// All derived metrics are pure functions. See scientific-methodology.md and offline evidence.
import {exerciseById} from './data.js';
export const dayNumber=d=>Date.parse(d+'T12:00:00Z')/86400000;
export const addDays=(d,n)=>new Date((dayNumber(d)+n)*86400000).toISOString().slice(0,10);
export const within=(date,end,days)=>date<=end&&dayNumber(date)>dayNumber(end)-days;
export function dailyCalories(entries,completeDays=[],end,days=30){const dates=Array.from({length:days},(_,i)=>addDays(end,i-days+1));return dates.map(date=>({date,value:entries.filter(x=>x.date===date).reduce((n,x)=>n+x.kcal,0),complete:completeDays.includes(date),logged:entries.some(x=>x.date===date)}))}
export function smoothWeight(entries,days=7){const sorted=[...entries].sort((a,b)=>a.date.localeCompare(b.date));return sorted.map(e=>{const window=sorted.filter(x=>x.date<=e.date&&dayNumber(e.date)-dayNumber(x.date)<days);return {date:e.date,value:window.reduce((s,x)=>s+x.kg,0)/window.length,observations:window.length}})}
export function regression(points){if(points.length<3)return null;const origin=dayNumber(points[0].date),x=points.map(p=>dayNumber(p.date)-origin),y=points.map(p=>p.value),mx=x.reduce((a,b)=>a+b)/x.length,my=y.reduce((a,b)=>a+b)/y.length,ss=x.reduce((a,v)=>a+(v-mx)**2,0);if(!ss)return null;const slope=x.reduce((a,v,i)=>a+(v-mx)*(y[i]-my),0)/ss,intercept=my-slope*mx,residual=y.reduce((a,v,i)=>a+(v-intercept-slope*x[i])**2,0);return {slope,intercept,standardError:Math.sqrt(residual/Math.max(1,x.length-2)/ss),span:Math.max(...x)-Math.min(...x),n:x.length}}
export function weightTrend(entries,end,days=28){const e=entries.filter(x=>within(x.date,end,days));const r=regression(e.map(x=>({date:x.date,value:x.kg})).sort((a,b)=>a.date.localeCompare(b.date)));return r&&r.span>=14&&r.n>=5?{...r,weekly:r.slope*7}:null}
export function rmr({age,height,sex},kg){if(!(age>=19&&age<=78&&height>=100&&height<=250&&kg>=25&&kg<=400&&['male','female'].includes(sex)))return null;return 10*kg+6.25*height-5*age+(sex==='male'?5:-161)}
export function tdee(profile,kg){if(profile.measuredTdee>0)return {value:profile.measuredTdee,method:'User-supplied maintenance estimate'};const rest=rmr(profile,kg);return rest?{value:rest*profile.activity,rmr:rest,method:'Mifflin–St Jeor × selected activity factor (heuristic)'}:null}
// Body weight for energy estimates: the 7-day mean of weigh-ins, unless the Settings weight was edited after the latest weigh-in.
export function currentWeight(state){const w=[...(state.weights||[])].sort((a,b)=>a.date.localeCompare(b.date)),last=w.at(-1),p=state.profile;if(p.weight>0&&(!last||(p.weightDate&&p.weightDate>=last.date)))return {kg:p.weight,source:'profile'};if(!last)return null;const m=smoothWeight(w).at(-1);return {kg:m.value,source:m.observations>1?'trend':'weigh-in',date:last.date}}
// Automatic daily calorie target: maintenance adjusted for the goal. Starting-point conventions from the cited reviews, not prescriptions. Fat loss: 20% below maintenance, at most 500 kcal (helms2014; murphy2022 found larger deficits blunted lean-mass gains). Muscle gain: a small surplus, 10% for beginners and 5% for trained lifters (iraki2019; helms2023 found a 5% surplus built muscle as well as 15% with less fat). Recomposition: 10% below maintenance. Never below the resting estimate. A reached target weight returns to maintenance.
export function calorieGoal(state){const p=state.profile,w=currentWeight(state),e=tdee(p,w?.kg);if(!e)return {ready:false,reason:p.measuredTdee>0?'':!(p.age>=19&&p.age<=78)?'Add your age (19 to 78) in Settings.':!p.height?'Add your height in Settings.':!w?'Add your weight in Settings or log a weigh-in.':!['male','female'].includes(p.sex)?'Choose the sex for the calorie formula in Settings.':'Complete your profile in Settings.'};const m=e.value,reached=p.targetWeight>0&&w&&(p.goal==='fat-loss'?w.kg<=p.targetWeight:p.goal==='muscle-growth'?w.kg>=p.targetWeight:false);let delta=0,label='Maintenance for your goal';if(!reached&&p.goal==='fat-loss'){delta=-Math.min(500,m*.2);label='Fat loss (20% less, max 500)'}else if(!reached&&p.goal==='muscle-growth'){const r=p.experience==='beginner'?.1:.05;delta=m*r;label='Muscle gain ('+r*100+'% more)'}else if(!reached&&p.goal==='recomposition'){delta=-m*.1;label='Recomposition (10% less)'}else if(reached)label='Target weight reached: maintenance';let value=m+delta;const floor=e.rmr||rmr(p,w?.kg);if(floor&&value<floor){value=floor;label+=' (raised to your resting estimate)'}value=Math.min(10000,Math.max(500,Math.round(value/10)*10));return {ready:true,value,maintenance:m,delta:value-m,label,method:e.method,weight:w}}
// Keeps an automatic target in step with the profile and weigh-ins. A custom target is left alone.
export function syncCalorieTarget(state){if(state.profile.calorieMode==='manual')return false;const g=calorieGoal(state);if(!g.ready||g.value===state.profile.calorieTarget)return false;state.profile.calorieTarget=g.value;return true}
export function adaptiveMaintenance(state,end){const complete=state.calorieDays||[],daily=dailyCalories(state.calories,complete,end,28).filter(x=>x.complete),weights=state.weights.filter(x=>within(x.date,end,28)),trend=weightTrend(weights,end,28),latest=[...weights].sort((a,b)=>a.date.localeCompare(b.date)).at(-1);if(daily.length<24||weights.length<8||!trend||trend.span<21)return {ready:false,reason:'Needs at least 24 complete calorie days and 8 weigh-ins spanning 21 days in the last 28 days.'};const average=daily.reduce((a,b)=>a+b.value,0)/daily.length;if(Math.abs(trend.weekly)>(latest?.kg||70)*.001)return {ready:false,reason:'Weight is changing. Intake alone cannot establish maintenance; review the trend and adjust gradually.',average,weekly:trend.weekly};return {ready:true,value:average,method:'Average recorded intake during approximately stable weight',reason:'Observed maintenance heuristic, not a measurement. Complete records, stable activity and fluid balance are assumed.',days:daily.length,weekly:trend.weekly}}
export function goalTimeline(weights,target,end){const r=weightTrend(weights,end,28),last=[...weights].filter(x=>x.date<=end).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);if(!r||!last||!target)return null;const gap=target-last.kg;if(Math.abs(gap)<.25)return {reached:true};if(gap*r.weekly<=0||Math.abs(r.weekly)<.05)return {reason:'The recent trend is not moving toward this target.'};const weeks=Math.abs(gap/r.weekly);if(weeks>8)return {reason:'The target is more than 8 weeks away at the recent pace. A long-range date would be unreliable.',weekly:r.weekly};return {weeks,range:[Math.max(1,Math.floor(weeks/1.5)),Math.ceil(weeks/.5)],weekly:r.weekly,n:r.n,method:'Short-range extrapolation of your recorded trend. Range assumes 50–150% of recent pace; it is a scenario band, not a statistical prediction interval.'}}
export function e1rm(load,reps,rir){if(!(load>0&&reps>=1&&reps<=10&&Number.isInteger(reps))||rir!==0)return null;if(reps===1)return load;return load*(1+reps/30)}
export function resistanceMetricsEligible(exerciseId){const e=exerciseById(exerciseId);return !!e&&e.category==='strength'&&e.tracking==='reps-load'&&!e.equipment.some(x=>['band','bodyweight','cable','machine'].includes(x))}
export function hasObservation(s,exerciseId){const tracking=exerciseById(exerciseId)?.tracking;return tracking==='duration'?s.duration>0:tracking==='duration-distance'?(s.duration>0||s.distance>0):s.reps>0}
export const workSets=e=>e.sets.filter(s=>s.done&&!s.warmup&&hasObservation(s,e.exerciseId));
export function muscleStats(sessions,exercises,groups,end,days=7){const result=Object.fromEntries(groups.map(g=>[g.id,{primary:0,secondary:0,days:new Set(),last:null,history:[]}]));for(const session of sessions){if(!within(session.date,end,days))continue;for(const item of session.exercises){const ex=exercises.find(e=>e.id===item.exerciseId);if(!ex||ex.category!=='strength')continue;const sets=workSets(item).length;for(const [role,ids]of [['primary',ex.primary],['secondary',ex.secondary]])for(const id of ids){if(!result[id]||!sets)continue;result[id][role]+=sets;result[id].days.add(session.date);if(!result[id].last||session.date>result[id].last)result[id].last=session.date;result[id].history.push({sessionId:session.id,date:session.date,exerciseId:ex.id,sets,role})}}}return Object.fromEntries(Object.entries(result).map(([id,v])=>[id,{...v,frequency:v.days.size,days:[...v.days]}]))}
export function performance(sessions,exerciseId){return sessions.filter(s=>s.exercises.some(e=>e.exerciseId===exerciseId)).sort((a,b)=>a.date.localeCompare(b.date)).flatMap(s=>{const items=s.exercises.filter(e=>e.exerciseId===exerciseId),sets=items.flatMap(workSets);if(!sets.length)return [];const loads=sets.map(x=>x.load).filter(x=>Number.isFinite(x)),reps=sets.map(x=>x.reps).filter(x=>x>0),estimates=resistanceMetricsEligible(exerciseId)?sets.map(x=>e1rm(x.load,x.reps,x.rir)).filter(x=>x!==null):[];const targets=[...new Set(items.map(x=>x.targetReps).filter(x=>Number.isInteger(x)&&x>0))];return [{date:s.date,sessionId:s.id,load:loads.length?Math.max(...loads):null,reps:reps.length?Math.max(...reps):null,volume:sets.some(x=>Number.isFinite(x.load)&&x.reps>0)?sets.reduce((a,x)=>a+(x.load??0)*(x.reps??0),0):null,e1rm:estimates.length?Math.max(...estimates):null,target:targets.length===1?targets[0]:null,sets}]})}
export function progression(sessions,exerciseId,explicitTarget){if(!resistanceMetricsEligible(exerciseId))return {ready:false,message:'Load suggestions are disabled for assistance, bands, bodyweight, machines, cables, and timed movements. Review repetitions, duration and your resistance convention directly.'};const history=performance(sessions,exerciseId);if(history.length<2)return {ready:false,message:'Log two comparable sessions before considering a change.'};const recent=history.slice(-2),target=explicitTarget??recent[1].target??12,consistent=explicitTarget!==undefined||recent.every(p=>(p.target??12)===target);if(!consistent)return {ready:false,target,message:'The recent sessions use different repetition targets. Compare sessions with the same target before changing load.'};const loads=recent.map(p=>p.sets.map(s=>s.load)),same=loads.every(ls=>ls.every(l=>l>0&&l===loads[0][0])),exceeded=recent.every(p=>p.sets.length>=2&&p.sets.every(s=>s.reps>=target+1&&s.rir!==null&&s.rir>=1));if(!same||!exceeded)return {ready:false,target,message:'Keep the load or add a controlled repetition. Recent sets do not consistently exceed the target with effort to spare.'};return {ready:true,target,load:loads[0][0]*1.025,message:'You exceeded the '+target+'-repetition target with at least 1 RIR at the same load in two sessions. Consider a small feasible increase (about 2–5%), then reassess.',note:'Two-session confirmation and the 2.5% calculation are conservative app heuristics; the historical ACSM load rule is 2–10%.'}}
export function lastSets(sessions,exerciseId){const s=sessions.filter(s=>s.exercises.some(e=>e.exerciseId===exerciseId&&workSets(e).length)).sort((a,b)=>a.date.localeCompare(b.date)||(a.startedAt||0)-(b.startedAt||0)).at(-1);return s?{date:s.date,sets:s.exercises.filter(e=>e.exerciseId===exerciseId).flatMap(workSets)}:null}
export const hrmax=age=>age>=18&&age<=100?208-.7*age:null;
export function hrBands(age,measured){const max=measured>0?measured:hrmax(age);return max?{max,moderate:[Math.round(.5*max),Math.round(.7*max)],vigorous:[Math.round(.7*max),Math.round(.85*max)],method:measured?'User-entered HRmax with AHA percent bands':'Tanaka age estimate with AHA percent bands'}:null}
export function metEnergy(met,kg,minutes){return met>=1&&kg>0&&minutes>0?{gross:met*kg*minutes/60,net:(met-1)*kg*minutes/60}:null}
export function bodyComposition(kg,percentage){return kg>0&&percentage>0&&percentage<75?{fat:kg*percentage/100,lean:kg*(1-percentage/100)}:null}
export function correlation(pairs){const n=pairs.length;if(n<7)return null;const ax=pairs.reduce((a,p)=>a+p[0],0)/n,ay=pairs.reduce((a,p)=>a+p[1],0)/n;let cov=0,sx=0,sy=0;for(const [x,y]of pairs){cov+=(x-ax)*(y-ay);sx+=(x-ax)**2;sy+=(y-ay)**2}return sx&&sy?{r:cov/Math.sqrt(sx*sy),n}:null}
export const kgToLb=kg=>kg/0.45359237;export const lbToKg=lb=>lb*.45359237;export const cmToIn=cm=>cm/2.54;export const inToCm=inch=>inch*2.54;
